+  private prepareCursorPagination(entity: Partial<T>, opts: CrudOptions) {
+    if (opts.cursor === undefined) {
+      if (!opts.orderBy || !opts.limit) {
+        return [];
+      }
+      const sort = this.getCursorSort(opts.orderBy);
+      opts.orderBy = this.toOrderBy(sort);
+      return sort;
+    }
+
+    if (!opts.orderBy) {
+      throw new BadRequestException('cursor requires orderBy');
+    }
+    if (opts.offset !== undefined) {
+      throw new BadRequestException('cursor cannot be used with offset');
+    }
+
+    const sort = this.getCursorSort(opts.orderBy);
+    const cursor = this.decodeCursor(opts.cursor, sort);
+    opts.orderBy = this.toOrderBy(sort);
+    Object.assign(entity, {
+      $and: [entity, this.getCursorQuery(cursor, sort)],
+    });
+    return sort;
+  }
+
+  private getCursorSort(orderBy: OrderByType<T>): CursorSortColumn[] {
+    const orderByParts = Array.isArray(orderBy) ? orderBy : [orderBy];
+    const sort = orderByParts.flatMap((part) =>
+      Object.entries(part).map(([field, value]) => ({
+        field,
+        direction: this.normalizeCursorDirection(value),
+      })),
+    );
+    const idField = this.crudConfig.id_field;
+    if (!sort.some((column) => column.field === idField)) {
+      sort.push({ field: idField, direction: 'asc' });
+    }
+    return sort;
+  }
+
+  private normalizeCursorDirection(value: unknown): 'asc' | 'desc' {
+    if (value === -1) {
+      return 'desc';
+    }
+    if (value === 1) {
+      return 'asc';
+    }
+    if (typeof value !== 'string') {
+      throw new BadRequestException('Invalid orderBy direction for cursor');
+    }
+    const direction = value.toLowerCase();
+    if (direction.startsWith('asc')) {
+      return 'asc';
+    }
+    if (direction.startsWith('desc')) {
+      return 'desc';
+    }
+    throw new BadRequestException('Invalid orderBy direction for cursor');
+  }
+
+  private toOrderBy(sort: CursorSortColumn[]): OrderByType<T> {
+    return sort.map(({ field, direction }) => ({ [field]: direction })) as any;
+  }
+
+  private decodeCursor(cursor: string, sort: CursorSortColumn[]) {
+    let payload: Record<string, any>;
+    try {
+      if (
+        !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(
+          cursor,
+        )
+      ) {
+        throw new Error('Invalid Base64');
+      }
+      payload = JSON.parse(Buffer.from(cursor, 'base64').toString('utf8'));
+    } catch {
+      throw new BadRequestException('Invalid cursor');
+    }
+
+    if (!payload || Array.isArray(payload) || typeof payload !== 'object') {
+      throw new BadRequestException('Invalid cursor');
+    }
+    const expectedSort = sort
+      .map(({ field, direction }) => `${field}:${direction}`)
+      .join(',');
+    if (payload.__sort !== expectedSort) {
+      throw new BadRequestException('Cursor orderBy does not match request');
